import spidev
import time

def read_analog_channel(channel, raw=False):
    if channel < 0 or channel > 7:
        return -1

    spi = spidev.SpiDev()
    try:
        spi.open(0, 0)
        spi.max_speed_hz = 1000000
        spi.mode = 0
        spi.lsbfirst = False

        # MCP3208 command format: start bit, single-ended, channel, MSB
        command = 0b11 << 6 | channel << 2
        response = spi.xfer2([command, 0, 0])

        # Extract the 12-bit result from the response
        adc_value = (response[1] << 8) | response[2]
        adc_value &= 0xFFF  # Mask to get the 12 bits

        if raw:
            return adc_value
        else:
            return adc_value / 4095.0
    except Exception as e:
        print(f"Error reading channel {channel}: {e}")
        return -1
    finally:
        spi.close()

def main():
    channels = [0, 1, 2]
    for channel in channels:
        result = read_analog_channel(channel)
        if result == -1:
            print(f"Failed to read channel {channel}.")
        else:
            print(f"Channel {channel}: {result}")

if __name__ == "__main__":
    main()

import spidev
import time
import signal
import sys

class LoadCellReader:
    def __init__(self, spi_device='/dev/spidev0.0'):
        self.spi = spidev.SpiDev()
        try:
            self.spi.open(0, 0)
            self.spi.max_speed_hz = 50000
            self.spi.mode = 0b00
            self.spi.bits_per_word = 8
        except (OSError, IOError) as e:
            print(f"Failed to open SPI device: {e}", file=sys.stderr)
            sys.exit(1)

    def read_raw_data(self):
        command = [1, (8 + 0) << 4, 0]
        try:
            response = self.spi.xfer2(command)
            return ((response[1] & 0x03) << 8) | response[2]
        except (OSError, IOError) as e:
            print(f"SPI read error: {e}", file=sys.stderr)
            return None

    def convert_to_weight(self, raw_code):
        # Assuming a calibration factor of 0.001 kg per raw code unit
        return raw_code * 0.001

    def close(self):
        self.spi.close()

def signal_handler(sig, frame):
    print("Program terminated by user")
    sys.exit(0)

def main():
    signal.signal(signal.SIGTERM, signal_handler)
    load_cell = LoadCellReader()

    try:
        while True:
            raw_data = load_cell.read_raw_data()
            if raw_data is not None:
                weight = load_cell.convert_to_weight(raw_data)
                print(f"Weight: {weight:.2f} kg")
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("Program interrupted by user")
    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
    finally:
        load_cell.close()
        print("SPI device closed and program terminated")

if __name__ == "__main__":
    main()

