import time
import queue
import threading
import logging
from gpiozero import DigitalInputDevice
from picamera2 import Picamera2
from adafruit_mcp3008 import MCP3008
import spidev
import argparse

logging.basicConfig(level=logging.INFO)
log_queue = queue.Queue()

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=log_queue):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.spi = None
        self.mcp = None
        self.digital_input = None
        self.running = False
        self.setup()

    def setup(self):
        try:
            if self.sensor_type == 'digital':
                self.digital_input = DigitalInputDevice(self.gpio_pins, pull_up=True)
            elif self.sensor_type == 'analog':
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.mcp = MCP3008(spi=self.spi, channel=self.channels)
            else:
                raise ValueError("Invalid sensor type")
        except Exception as e:
            logging.error(f"Failed to setup sensor {self.sensor_id}: {e}")

    def run(self):
        self.running = True
        try:
            while self.running:
                if self.sensor_type == 'digital':
                    if self.digital_input.is_active:
                        self.log_event("Digital sound detected")
                elif self.sensor_type == 'analog':
                    adc_value = self.mcp.value
                    if adc_value >= self.threshold:
                        self.log_event(f"Analog sound detected, value: {adc_value}")
                time.sleep(1 / self.sample_rate)
        except KeyboardInterrupt:
            pass
        finally:
            self.stop()

    def stop(self):
        self.running = False
        if self.spi:
            self.spi.close()
        if self.sensor_type == 'digital' and self.digital_input:
            self.digital_input.close()

    def log_event(self, message):
        self.log_queue.put(f"Sensor {self.sensor_id}: {message}")

def main():
    parser = argparse.ArgumentParser(description="Sound sensor monitoring")
    parser.add_argument("--sensor_type", required=True, choices=['digital', 'analog'], help="Type of sensor")
    parser.add_argument("--threshold", type=int, required=True, help="Threshold for analog sensor")
    parser.add_argument("--sample_rate", type=int, required=True, help="Sample rate in Hz")
    parser.add_argument("--log_file", help="Log file path")
    parser.add_argument("--gpio_pins", type=int, nargs='+', required=True, help="GPIO pins for digital sensors")
    parser.add_argument("--channels", type=int, nargs='+', required=True, help="MCP3008 channels for analog sensors")
    parser.add_argument("--spi_speed", type=int, default=1000000, help="SPI speed in Hz")
    parser.add_argument("--sensor_ids", type=int, nargs='+', required=True, help="Sensor IDs")
    args = parser.parse_args()

    sensors = []
    for i, sensor_id in enumerate(args.sensor_ids):
        sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins[i], args.channels[i], args.spi_speed)
        sensors.append(sensor)
        threading.Thread(target=sensor.run).start()

    try:
        while True:
