I2C_ADDRESS = 0x29
LOG_FILE = 'occupancy.log'
MAX_TOF_READINGS = 3
TOF_DELAY = 0.1
MA_SIZE = 5
MA_THRESHOLD = 1000  # 1 meter in mm

# Global variables
log_file = None
tof_sensor = None
motion_sensors = []
tof_readings = []

def init_logging():
    global log_file
    try:
        log_file = open(LOG_FILE, 'a')
    except IOError as e:
        print(f"Error opening log file: {e}")
        exit(1)

def init_tof_sensor():
    global tof_sensor
    i2c = busio.I2C(I2C_SCL, I2C_SDA)
    try:
        tof_sensor = VL53L0X(i2c, I2C_ADDRESS)
    except Exception as e:
        print(f"Error initializing ToF sensor: {e}")
        exit(1)

def init_motion_sensors():
    global motion_sensors
    for pin in PIR_PINS:
        try:
            motion_sensors.append(MotionSensor(pin, queue_len=1, threshold=0.5, sample_rate=1))
        except Exception as e:
            print(f"Error initializing motion sensor on pin {pin}: {e}")
            exit(1)

def read_tof_sensor():
    global tof_readings
    valid_readings = []
    for _ in range(MAX_TOF_READINGS):
        try:
            distance = tof_sensor.range
            if distance > 0:
                valid_readings.append(distance)
        except Exception as e:
            print(f"Error reading ToF sensor: {e}")
        time.sleep(TOF_DELAY)
    tof_readings = valid_readings

def moving_average(values, size):
    if len(values) < size:
        return sum(values) / len(values)
    return sum(values[-size:]) / size

def log_event(zone, distance, validated):
    log_file.write(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Zone {zone}: Distance {distance} mm, Validated {validated}\n")
    log_file.flush()

def handle_sigterm(signum, frame):
    cleanup()
    exit(0)

def cleanup():
    global log_file, tof_sensor, motion_sensors
    if log_file:
        log_file.close()
    if tof_sensor:
        tof_sensor.stop_ranging()
    for sensor in motion_sensors:
        sensor.close()

def main():
    init_logging()
    init_tof_sensor()
    init_motion_sensors()
    atexit.register(cleanup)
    signal.signal(signal.SIGTERM, handle_sigterm)

    while True:
        for i, sensor in enumerate(motion_sensors):
            if sensor.motion_detected:
                read_tof_sensor()
                avg_distance = moving_average(tof_readings, MA_SIZE)
                validated = avg_distance < MA_THRESHOLD
                log_event(i + 1, avg_distance, validated)
                time.sleep(2)  # Debounce for 2 seconds

if __name__ == "__main__":
    main()

