import io
import time
import logging
import numpy as np
from picamera2 import Picamera2, MjpegDecoder
from paho.mqtt import client as mqtt_client

# Setup logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class CameraStreamBuffer:
    def __init__(self, output_sink, encode_metadata=True, complete_frame_flag=False):
        self.output_sink = output_sink
        self.encode_metadata = encode_metadata
        self.complete_frame_flag = complete_frame_flag
        self.buffer = io.BytesIO()
        self.frame_start = None
        self.frame_end = None

    def write(self, data):
        self.buffer.write(data)
        while True:
            if self.frame_start is None:
                self.frame_start = self.buffer.getvalue().find(b'\xff\xd8')
                if self.frame_start == -1:
                    break
            self.frame_end = self.buffer.getvalue().find(b'\xff\xd9', self.frame_start)
            if self.frame_end == -1:
                break
            frame_data = self.buffer.getvalue()[self.frame_start:self.frame_end + 2]
            self.buffer.seek(self.frame_end + 2)
            if self.encode_metadata or self.complete_frame_flag:
                try:
                    self.output_sink.write(frame_data)
                except IOError as e:
                    logger.error(f"I/O error: {e}")
            self.frame_start = None

class MotionDetectionBuffer:
    def __init__(self, callback):
        self.callback = callback
        self.previous_frame = None
        self.decoder = MjpegDecoder()

    def write(self, data):
        if self.previous_frame is None:
            self.previous_frame = self.decode_frame(data)
            return
        current_frame = self.decode_frame(data)
        if current_frame is not None:
            try:
                self.callback(self.previous_frame, current_frame)
            except Exception as e:
                logger.error(f"Callback error: {e}")
            self.previous_frame = current_frame

    def decode_frame(self, data):
        try:
            frame = self.decoder.decode(data)
            return frame
        except Exception as e:
            logger.error(f"Decode error: {e}")
            return None

# Example usage
