class AnimatedGif:
    def __init__(self, display, folder_path, width=None, height=None):
        self.display = display
        self.width = width or display.width
        self.height = height or display.height
        self.folder_path = folder_path
        self.gifs = []
        self._is_running = False

    def load_files(self):
        self.gifs = []
        for filename in os.listdir(self.folder_path):
            if filename.endswith('.gif'):
                file_path = os.path.join(self.folder_path, filename)
                try:
                    with Image.open(file_path) as img:
                        if img.is_animated:
                            self.gifs.append((file_path, img))
                except Exception as e:
                    logger.error(f"Error loading {file_path}: {e}")
        if not self.gifs:
            raise FileNotFoundError("No valid GIFs found in the folder.")

    def preload(self):
        for file_path, img in self.gifs:
            try:
                frames = []
                for frame in ImageSequence.Iterator(img):
                    frame = frame.convert('RGB')
                    frame = ImageOps.pad(frame, (self.width, self.height), color='black', centering=(0.5, 0.5))
                    frames.append(frame)
                self.gifs = [(file_path, frames, img.info['loop'])]
            except Exception as e:
                logger.error(f"Error preloading {file_path}: {e}")
                self.gifs = []

    def play(self):
        if not self.gifs:
            return False
        for file_path, frames, loop in self.gifs:
            start_time = time.monotonic()
            loop_count = 0
            while True:
                for frame in frames:
                    current_time = time.monotonic()
                    elapsed_time = current_time - start_time
                    sleep_time = (frame.info['duration'] / 1000) - (elapsed_time - start_time)
                    sleep_time = max(sleep_time, 0)
                    time.sleep(sleep_time)
                    self.display.display(frame)
                loop_count += 1
                if loop == 0 or loop_count == loop:
                    return True
        return False

    def run(self):
        self._is_running = True
        while self._is_running:
            if not self.play():
                break

    def stop(self):
        self._is_running = False

def signal_handler(signum, frame):
    logger.info("Shutting down...")
    animated_gif.stop()
    display.close()
    camera2.stop()
    exit(0)

