            return None, None, True

        try:
            self.bus.write_byte_data(self.I2C_ADDRESS, self.DATA_REG, 0x01)
            start_time = time.time()
            while time.time() - start_time < 0.1:
                status = self.bus.read_byte_data(self.I2C_ADDRESS, self.STATUS_REG)
                if status & 0x01 == 0:
                    break
                time.sleep(0.01)
            else:
