            if crc != data[6]:
                return None, None, True

            humidity = humidity_raw / 1024.0
            temperature = temperature_raw / 1024.0

            return temperature, humidity, False
        except Exception as e:
            print(f"Measurement failed: {e}")
            return None, None, True

