import time
import board
import busio
import adafruit_dht
import logging
from contextlib import contextmanager

# Setup logging
logging.basicConfig(level=logging.WARNING)
logger = logging.getLogger(__name__)

class DHT20Driver:
    def __init__(self, i2c_bus=1, power_on_delay=0.5, status_poll_interval=0.08, max_status_polls=10, max_attempts=5, min_interval=2):
        self.i2c = busio.I2C(board.SCL, board.SDA)
        self.dht = adafruit_dht.DHT20(self.i2c, address=0x44)
        self.power_on_delay = power_on_delay
        self.status_poll_interval = status_poll_interval
        self.max_status_polls = max_status_polls
        self.max_attempts = max_attempts
        self.min_interval = min_interval
        self.last_read_time = 0
        self.last_temperature = None
        self.last_humidity = None

    def begin(self):
        time.sleep(self.power_on_delay)
        try:
            self.dht.temperature
            self.dht.humidity
            return True
        except OSError as e:
            logger.error(f"Failed to initialize DHT20: {e}")
            return False

    def get_temperature_and_humidity(self):
        current_time = time.time()
        if current_time - self.last_read_time < self.min_interval:
            return self.last_temperature, self.last_humidity, False

        for attempt in range(self.max_attempts):
            try:
                temperature = self.dht.temperature
                humidity = self.dht.humidity
                return temperature, humidity, False
            except OSError as e:
                if "CRC error" in str(e):
                    logger.warning(f"CRC error in DHT20 data, retrying...")
                else:
                    logger.error(f"Failed to read DHT20: {e}")
                    return None, None, True

        return None, None, True

    def close(self):
        self.dht.exit()
        self.i2c.deinit()

    @contextmanager
    def managed(self):
        try:
            yield self
        finally:
            self.close()

def demo():
    try:
        with DHT20Driver() as driver:
            if not driver.begin():
                print("Failed to initialize DHT20, exiting.")
                return 0

            while True:
                temperature, humidity, error = driver.get_temperature_and_humidity()
                if error:
                    print("Failed to read DHT20, retrying...")
                else:
                    print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                time.sleep(1)
    except (KeyboardInterrupt, SystemExit):
        print("Exiting demo.")
        return 0

if __name__ == "__main__":
    exit_code = demo()
    exit(exit_code)

