        temp = float(temp_str.split('=')[1].split('.')[0])
        return temp
    except subprocess.CalledProcessError as e:
        print(f"Error reading CPU temperature: {e}", file=sys.stderr)
        return None

def set_fan_duty_cycle(duty_cycle):
    global last_duty_cycle
    if fan:
        fan.value = duty_cycle / 100.0
    last_duty_cycle = duty_cycle

def signal_handler(sig, frame):
    print("Received signal to stop, shutting down gracefully...")
    if fan:
        fan.stop()
    sys.exit(0)

def main():
    global fan
    fan = PWMOutputDevice(FAN_PIN, frequency=FAN_FREQ)
    signal.signal(SIGINT, signal_handler)
    signal.signal(SIGTERM, signal_handler)

    while True:
        temp = read_cpu_temperature()
        if temp is not None:
            if temp > TEMPERATURE_THRESHOLD:
                set_fan_duty_cycle(100)
            else:
                set_fan_duty_cycle(0)
        else:
            set_fan_duty_cycle(last_duty_cycle)

        time.sleep(5)

if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
        if fan:
            fan.stop()
        sys.exit(1)

import serial
import time
import logging
from contextlib import contextmanager

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
UART_PORT = '/dev/ttyUSB0'
UART_BAUDRATE = 9600
ALERT_TEMP = 30.0
ALERT_HUMIDITY = 70.0

@contextmanager
def open_uart(port, baudrate):
    try:
        ser = serial.Serial(port, baudrate, timeout=1)
        yield ser
    except serial.SerialException as e:
        logging.error(f"Failed to open UART port {port}: {e}")
    finally:
        if 'ser' in locals() and ser.is_open:
            ser.close()
            logging.info(f"Closed UART port {port}")

def read_sensor_data(ser):
    try:
        line = ser.readline().decode('utf-8').strip()
        if not line:
            raise ValueError("Empty line received")
        temp, humidity = map(float, line.split(','))
        return temp, humidity
    except (ValueError, serial.SerialException) as e:
        logging.error(f"Error reading sensor data: {e}")
        return None, None

def main():
    while True:
        try:
            with open_uart(UART_PORT, UART_BAUDRATE) as ser:
                temp, humidity = read_sensor_data(ser)
                if temp is not None and humidity is not None:
                    logging.info(f"Temperature: {temp:.1f}°C, Humidity: {humidity:.1f}%")
                    if temp > ALERT_TEMP or humidity > ALERT_HUMIDITY:
                        logging.warning(f"Alert: Temperature {temp:.1f}°C or Humidity {humidity:.1f}% exceeds threshold")
        except KeyboardInterrupt:
            logging.info("Program interrupted by user")
            break
        except Exception as e:
            logging.error(f"Unexpected error: {e}")
        time.sleep(1)

if __name__ == "__main__":
    main()

