    global log_file
    if log_file:
        log_file.write(data + "\n")
        log_file.flush()

def receive_data():
    global log_file
    while True:
        data = dog.receive()
        if data:
            log_data(data)

def signal_handler(sig, frame):
    global log_file, log_thread
    print("Exiting...")
    if log_file:
        log_file.close()
    if log_thread and log_thread.is_alive():
        log_thread.join()
    camera.close()
    led.close()
    mqtt_client.disconnect()
    sys.exit(0)

