                elif command[1] == "exit":
                    print("Usage: exit")
                else:
                    print(f"Unknown command: {command[1]}")
            else:
                print("Usage: help [command]")

        elif command[0] == "display":
            if log_file:
                log_file.seek(0)
                print(log_file.read())
            else:
                print("No log file is open.")

        elif command[0] == "send":
            if len(command) != 2:
