import paho.mqtt.client as mqtt

class OccupancyMonitor:
    def __init__(self, gpio_pin=17, debounce_interval=2.0, sample_count=10):
        self.gpio_pin = gpio_pin
        self.debounce_interval = debounce_interval
        self.sample_count = sample_count
        self.events = []
        self.sensor = None
        self.client = None

    def init_sensor(self):
        try:
            self.sensor = MotionSensor(self.gpio_pin, queue_size=1)
            self.sensor.when_motion = self.on_motion
            self.client = mqtt.Client()
            self.client.connect("mqtt.eclipse.org", 1883, 60)
            self.client.loop_start()
        except Exception as e:
            print(f"Failed to initialize sensor: {e}")
            return False
        return True

    def on_motion(self):
        if not self.sensor.active:
            return
        event_time = datetime.now().isoformat()
        self.events.append(event_time)
        if len(self.events) > self.sample_count:
            self.events.pop(0)
        self.client.publish("occupancy/events", event_time)

    def get_occupancy_stats(self):
        return {
            "total_events": len(self.events),
            "last_event": self.events[-1] if self.events else None
        }

    def cleanup(self):
        if self.sensor:
            self.sensor.close()
        if self.client:
            self.client.loop_stop()
            self.client.disconnect()

