import atexit
import logging
import signal
import time
from gpiozero import PWMOutputDevice, DigitalOutputDevice
from picamera2 import Picamera2
from paho.mqtt.client import Client, MQTTMessage
from zmq import Context, Poller, POLLIN

# Setup logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class PIDHandler:
    def __init__(self, pwm_flag: bool):
        self.pwm_flag = pwm_flag
        self.last_msg = time.time()
        self.global_err_state = False
        self.pwm_output = None
        self.digital_output = None
        self.context = Context()
        self.socket = self.context.socket(zmq.SUB)
        self.poller = Poller()
        self.poller.register(self.socket, POLLIN)
        self.initialize_gpio()
        self.initialize_mqtt()

    def initialize_gpio(self):
        try:
            if self.pwm_flag:
                self.pwm_output = PWMOutputDevice(18, frequency=1000, initial_value=0.0)
            else:
                self.digital_output = DigitalOutputDevice(15)
        except Exception as e:
            logger.error(f"Failed to initialize GPIO: {e}")
            self.cleanup()
            exit(1)

    def initialize_mqtt(self):
        self.socket.connect("tcp://localhost:5555")
        self.socket.setsockopt_string(zmq.SUBSCRIBE, "")

    def update_error_output(self):
        if self.pwm_output:
            self.pwm_output.value = self.global_err_state
        else:
            self.digital_output.value = self.global_err_state

    def set_error_output(self, state: bool):
        self.global_err_state = state
        self.update_error_output()

    def handle_message(self):
        socks = dict(self.poller.poll(20000))
        if self.socket in socks:
            msg = self.socket.recv_multipart()
            self.last_msg = time.time()
            # Process subscription callbacks here
            logger.info(f"Received message: {msg}")
        else:
            if time.time() - self.last_msg > 20:
                self.set_error_output(True)
                logger.warning("No message received for 20 seconds, setting error output to True")

    def cleanup(self):
        if self.pwm_output:
            self.pwm_output.close()
        if self.digital_output:
            self.digital_output.close()
        self.socket.close()
        self.context.term()

    def signal_handler(self, sig, frame):
        logger.info(f"Received signal {sig}, cleaning up and exiting")
        self.cleanup()
        exit(0)

def main():
