import time
from gpiozero import OutputDevice, Device
from gpiozero.pins.pigpio import PiGPIOFactory
from gpiozero.exc import DeviceClosed
from typing import Optional

class OutputPin:
    def __init__(self, pin_number: int, initial_value: int):
        if not (0 <= pin_number <= 31):
            raise ValueError("pin_number must be between 0 and 31")
        if initial_value not in (0, 1):
            raise ValueError("initial_value must be 0 or 1")

        self.pin_number = pin_number
        self.initial_value = initial_value
        self.device: Optional[OutputDevice] = None

        try:
            Device.pin_factory = PiGPIOFactory()
            self.device = OutputDevice(pin_number, initial_value=initial_value)
        except Exception as e:
            raise Exception("Failed to initialize GPIO driver daemon") from e

    def set_value(self, value: int):
        if value not in (0, 1):
            raise ValueError("value must be 0 or 1")
        if self.device is None:
            raise DeviceClosed("Device is closed")
        self.device.value = value

    def shutdown(self):
        if self.device is not None:
            self.device.close()
            self.device = None

if __name__ == '__main__':
    pin = OutputPin(17, 0)
    try:
        for _ in range(10):
            pin.set_value(1 - pin.device.value)
            time.sleep(0.5)
    finally:
        pin.shutdown()

