from gpiozero import Button, LED
from gpiozero.pins.native import NativePin
from signal import signal, SIGINT, SIGTERM

class RotaryEncoder:
    def __init__(self, clk_pin, dt_pin, callback=None, debounce=0.005):
        if not callable(callback):
            raise ValueError("Callback must be callable")

        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.debounce = debounce
        self.counter = 0
        self.last_clk_state = False
        self.last_dt_state = False
        self.event_thread = None
        self.running = False

        self.clk_button = Button(clk_pin, pull_up=True, bounce_time=debounce)
        self.dt_button = Button(dt_pin, pull_up=True, bounce_time=debounce)

        self.clk_button.when_pressed = self.on_clk_press
        self.dt_button.when_pressed = self.on_dt_press

        self.start_event_thread()

    def start_event_thread(self):
        self.running = True
        self.event_thread = threading.Thread(target=self.event_loop)
        self.event_thread.start()

    def event_loop(self):
        while self.running:
            time.sleep(0.01)

    def on_clk_press(self):
        current_clk_state = self.clk_button.is_pressed
        current_dt_state = self.dt_button.is_pressed

        if current_clk_state != self.last_clk_state:
            if current_dt_state != self.last_dt_state:
                self.counter += 1
            else:
                self.counter -= 1

            if self.callback:
                try:
                    self.callback(self.counter)
                except Exception as e:
                    print(f"Callback error: {e}")

            self.last_dt_state = current_dt_state
            self.last_clk_state = current_clk_state

    def cleanup(self):
        self.running = False
        if self.event_thread:
