class LEDController:
    def __init__(self, pin=25):
        try:
            self.led = LED(pin, pin_factory=NativePinFactory())
        except BadPinFactory as e:
            raise ValueError(f"Invalid pin number: {e}")
        except OutputDeviceError as e:
            raise RuntimeError(f"Failed to initialize LED: {e}")

    def on(self):
        self.led.on()

    def off(self):
        self.led.off()

    def blink(self, on_duration, off_duration):
        if on_duration < 0 or off_duration < 0:
            raise ValueError("On and off durations must be non-negative")
        self.on()
        time.sleep(on_duration)
        self.off()
        time.sleep(off_duration)

def signal_handler(sig, frame):
    print("Received signal, turning LED off and exiting...")
    led_controller.off()
    sys.exit(0)

if __name__ == "__main__":
    led_controller = LEDController()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            led_controller.blink(1.0, 0.5)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        led_controller.off()

