import RPi.GPIO as GPIO
import time

class MotorError(Exception):
    pass

class Motor:
    def __init__(self, driver, pin):
        self.driver = driver
        self.pin = pin
        self.pwm = None
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.OUT)
            self.pwm = GPIO.PWM(self.pin, 1000)
            self.pwm.start(0)
        except Exception as e:
            raise MotorError(f"Failed to initialize motor: {e}")

    def set_frequency(self, freq):
        try:
            self.pwm.ChangeFrequency(freq)
        except Exception as e:
            raise MotorError(f"Failed to set frequency: {e}")

    def set_duty_cycle(self, duty):
        if not 0 <= duty <= 255:
            raise MotorError("Duty cycle must be in the range 0-255")
        try:
            self.pwm.ChangeDutyCycle(duty)
        except Exception as e:
            raise MotorError(f"Failed to set duty cycle: {e}")

    def stop(self):
        self.set_duty_cycle(0)

    def __del__(self):
        self.stop()
        GPIO.cleanup()

    def close(self):
        self.stop()
        GPIO.cleanup()

