class ModbusRTUServo:
    def __init__(self, port, baudrate, slave_address):
        self.port = port
        self.baudrate = baudrate
        self.slave_address = slave_address
        self.client = None
        self.setup()

    def setup(self):
        try:
            self.client = RTUClient(self.port, baudrate=self.baudrate, timeout=1)
            self.client.connect()
        except Exception as e:
            print(f"Failed to open serial port: {e}")
            sys.exit(1)

    def move_motor(self, position):
        if not isinstance(position, int) or position < 0 or position > 100:
            return -1  # Invalid position
        try:
            self.client.write_register(0, position, unit=self.slave_address)
            return 0  # Success
        except ModbusIOException as e:
            print(f"Modbus I/O error: {e}")
            return -2
        except ModbusNoResponseException as e:
            print(f"Modbus no response: {e}")
            return -3
        except ModbusSlaveException as e:
            print(f"Modbus slave error: {e}")
            return -4

