import serial
import time
import signal
import sys
from gpiozero import OutputDevice
from contextlib import contextmanager

class GSMModule:
    def __init__(self, port='/dev/serial0', baudrate=115200, power_pin=4, timeout=2):
        self.port = port
        self.baudrate = baudrate
        self.power_pin = power_pin
        self.timeout = timeout
        self.ser = None
        self.power = OutputDevice(power_pin)
        self.setup()

    def setup(self):
        self.power.on()
        time.sleep(2)
        self.ser = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
        time.sleep(3)
        self.verify_connection()

    def verify_connection(self):
        self.send_at_command('AT')
        response = self.read_response()
        if response and 'OK' in response:
            print("Module is responsive.")
        else:
            raise Exception("Module is not responsive.")

    def send_at_command(self, command):
        print(f"Sending: {command}")
        self.ser.write((command + '\r\n').encode())

    def read_response(self):
        response = ''
        for _ in range(5):
            if self.ser.in_waiting > 0:
                response += self.ser.read(self.ser.in_waiting).decode()
                if 'OK' in response or 'ERROR' in response:
                    break
            time.sleep(0.1)
        print(f"Received: {response}")
        return response if 'OK' in response else None

    def set_gps_reporting(self, interval_seconds=10):
        self.send_at_command(f'AT+GPSRD={interval_seconds}')
        response = self.read_response()
        if response and 'OK' in response:
            print("GPS reporting set successfully.")
        else:
            raise Exception("Failed to set GPS reporting.")

    def set_message_storage(self, storage='SM'):
        self.send_at_command(f'AT+CPMS="{storage}","{storage}","{storage}"')
        response = self.read_response()
        if response and 'OK' in response:
            print("Message storage set successfully.")
        else:
            raise Exception("Failed to set message storage.")

    def send_tcp_data(self, data, ip='192.168.100.12', port=50):
        self.send_at_command(f'AT+CIPSTART="TCP","{ip}",{port}')
        response = self.read_response()
        if response and 'OK' in response:
            print("TCP connection established.")
            self.send_at_command(f'AT+CIPSEND={len(data)}')
            response = self.read_response()
            if response and '>' in response:
                self.ser.write((data + '\x1A').encode())
                response = self.read_response()
                if response and 'SEND OK' in response:
                    print("Data sent successfully.")
                else:
                    raise Exception("Failed to send data.")
            else:
                raise Exception("Failed to enter send mode.")
        else:
            raise Exception("Failed to establish TCP connection.")

    def send_terminator(self):
        self.ser.write('\x1A'.encode())
        response = self.read_response()
        if response and 'SEND OK' in response:
            print("Terminator sent successfully.")
        else:
            raise Exception("Failed to send terminator.")

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.ser.close()
        self.power.off()

def signal_handler(sig, frame):
    print('You pressed Ctrl+C!')
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    with GSMModule() as gsm:
        gsm.set_gps_reporting()
        gsm.set_message_storage()
        gsm.send_tcp_data("Hello, GSM!")
        gsm.send_terminator()

