def handle_message(message: MQTTMessageInfo):
    phrase = message.payload.decode('utf-8').lower()
    intent = parse_intent(phrase)
    if intent:
        apply_intent(intent)
        print(f"Applied intent: {intent} for phrase: {phrase}")
    else:
        print(f"Unknown intent for phrase: {phrase}")

