import time
import signal
import sys
from datetime import datetime
from gpiozero import I2C
from picamera2 import Picamera2
from adafruit_circuitpython_ds1338 import DS1338
from paho.mqtt import client as mqtt_client

# Constants
DS1338_I2C_ADDRESS = 0x68
I2C_SDA_PIN = 2
I2C_SCL_PIN = 3
DEFAULT_CENTURY = 21

# Global variables
i2c = None
rtc = None
picamera2 = None

def signal_handler(sig, frame):
    print("Exiting gracefully...")
    cleanup()
    sys.exit(0)

def cleanup():
    global i2c, rtc, picamera2
    if rtc:
        rtc.deinit()
    if i2c:
        i2c.close()
    if picamera2:
        picamera2.stop()
        picamera2.close()

def bcd_to_int(bcd):
    return (bcd >> 4) * 10 + (bcd & 0x0F)

def int_to_bcd(value):
    return ((value // 10) << 4) | (value % 10)

def read_datetime(century=DEFAULT_CENTURY):
    try:
        dt = rtc.datetime
        year = bcd_to_int(dt[0]) + (century - 1) * 100
        month = bcd_to_int(dt[1])
        day = bcd_to_int(dt[2])
        hour = bcd_to_int(dt[3]) & 0x3F  # Mask bit 6
        minute = bcd_to_int(dt[4])
        second = bcd_to_int(dt[5])
        return datetime(year, month, day, hour, minute, second)
    except OSError as e:
        print(f"Error reading RTC: {e}")
        return None

def write_all(year=None, month=None, day=None, hour=None, minute=None, second=None):
    try:
        dt = list(rtc.datetime)
        if year is not None:
            dt[0] = int_to_bcd(year % 100)
        if month is not None:
            dt[1] = int_to_bcd(month)
        if day is not None:
            dt[2] = int_to_bcd(day)
        if hour is not None:
            dt[3] = int_to_bcd(hour) & 0x3F  # Mask bit 6
        if minute is not None:
            dt[4] = int_to_bcd(minute)
        if second is not None:
            dt[5] = int_to_bcd(second)
        rtc.datetime = tuple(dt)
    except OSError as e:
        print(f"Error writing to RTC: {e}")

def main():
    global i2c, rtc, picamera2
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        i2c = I2C(I2C_SDA_PIN, I2C_SCL_PIN)
        rtc = DS1338(i2c, address=DS1338_I2C_ADDRESS)
        picamera2 = Picamera2()

        # Verify RTC presence
        if not rtc.datetime:
            print("RTC not found or not initialized.")
            return

