import serial
import signal
import sys
import time

class ESP8266Control:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.ser = None
        try:
            self.ser = serial.Serial(self.port, self.baud_rate, timeout=self.timeout)
        except serial.SerialException as e:
            print(f"Failed to open UART port {self.port}: {e}")
            sys.exit(1)

    def __del__(self):
        if self.ser:
            self.ser.close()

    def _send_command(self, command, expected_responses=None, timeout=None):
        if timeout is None:
            timeout = self.timeout
        self.ser.write((command + '\r\n').encode())
        start_time = time.time()
        response = b''
        while time.time() - start_time < timeout:
            if self.ser.in_waiting > 0:
                response += self.ser.read(self.ser.in_waiting)
                if expected_responses and any(response.endswith(e) for e in expected_responses):
                    return response
        return None

    def test_connection(self):
        response = self._send_command('AT', [b'OK'])
        return response == b'OK'

    def restart(self):
        self._send_command('AT+RST', [b'OK', b'ready'], timeout=5.0)
        time.sleep(2)
        return self.test_connection()

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP="{ssid}","{password}"'
        response = self._send_command(command, [b'OK'], timeout=10.0)
        return response == b'OK'

    def disconnect_wifi(self):
        self._send_command('AT+CWQAP', [b'OK'])

    def get_ip(self):
        response = self._send_command('AT+CIFSR', [b'OK'])
        if response:
            lines = response.decode().split('\r\n')
            for line in lines:
                if 'STAIP' in line:
                    return line.split(':')[1].strip().strip('"')
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        if headers is None:
            headers = {}
        if data is None:
            data = b''

        command = f'AT+CIPSTART="TCP","{host}",{port}'
        response = self._send_command(command, [b'OK'], timeout=5.0)
        if response != b'OK':
            return None

        request = f"{method} {url} HTTP/1.1\r\nHost: {host}\r\n"
        for key, value in headers.items():
            request += f"{key}: {value}\r\n"
        request += f"Content-Length: {len(data)}\r\n\r\n{data.decode()}"

        self._send_command(f'AT+CIPSEND={len(request)}', [b'>'], timeout=5.0)
        self.ser.write(request.encode())

        response = self._send_command('', [b'+IPD,', b'CLOSED'], timeout=10.0)
        if response and b'+IPD,' in response:
            parts = response.split(b'+IPD,')
            length = int(parts[1].split(b':')[0])
            payload = parts[1].split(b':')[1].split(b'\r\n\r\n')[1][:length]
            return payload
        return None

    def receive_http_response(self, timeout=5.0):
        response = self._send_command('', [b'+IPD,', b'CLOSED'], timeout=timeout)
        if response and b'+IPD,' in response:
            parts = response.split(b'+IPD,')
            length = int(parts[1].split(b':')[0])
            payload = parts[1].split(b':')[1].split(b'\r\n\r\n')[1][:length]
            return payload
        return None

def signal_handler(sig, frame):
    print('Exiting gracefully...')
    sys.exit(0)

if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    esp = ESP8266Control()
    if esp.test_connection():
        print("ESP8266 is connected.")
        if esp.connect_wifi('your_ssid', 'your_password'):
            print("Connected to WiFi.")
            ip = esp.get_ip()
            if ip:
                print(f"IP Address: {ip}")
                response = esp.send_http_request('GET', '/', 'example.com')
                if response:
                    print("HTTP Response:")
                    print(response)
                esp.disconnect_wifi()
            else:
                print("Failed to get IP address.")
        else:
            print("Failed to connect to WiFi.")
    else:
        print("Failed to connect to ESP8266.")

