import sys
import time

class ESP8266:
    def __init__(self):
        try:
            self.ser = serial.Serial(
                port='/dev/ttyS0',
                baudrate=115200,
                timeout=5,
                xonxoff=False,
                rtscts=False,
                dsrdtr=False,
                write_timeout=5
            )
        except serial.SerialException as e:
            print(f"Failed to open UART port: {e}")
            sys.exit(1)

    def __del__(self):
        self.ser.close()

    def _send_command(self, command, delay=1, max_retries=3):
        for _ in range(max_retries):
            self.ser.write(command.encode('utf-8') + b'\r\n')
            time.sleep(delay)
            response = self._read_response()
            if response in ['OK', 'ERROR', 'FAIL']:
                return response
        return None

    def _read_response(self):
        try:
            response = self.ser.read_until(b'\r\n', timeout=5).decode('utf-8').strip()
            return response
        except serial.SerialTimeoutException:
            return None

    def test_connection(self):
        return self._send_command('AT') == 'OK'

    def restart(self):
        response = self._send_command('AT+RST', delay=2)
        return response == 'OK'

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP_CUR="{ssid}","{password}"'
        response = self._send_command(command, delay=5)
        return 'WIFI GOT IP' in response

def signal_handler(sig, frame):
    print('Exiting gracefully...')
    sys.exit(0)

if __name__ == '__main__':
