import serial
import signal
import sys
import time

class GPSController:
    def __init__(self, port='/dev/ttyAMA0', baud=9600):
        try:
            self.ser = serial.Serial(port, baud, timeout=1)
        except serial.SerialException as e:
            raise IOError(f"Failed to open port {port}: {e}") from e

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def attach(self):
        try:
            self.ser.write(b"AT+CGNSPWR=1\r\n")
            time.sleep(1)
            response = self.ser.readline().decode('utf-8').strip()
            if response != "OK":
                raise IOError(f"Failed to power on GNSS: {response}")
            return True
        except serial.SerialException as e:
            raise IOError(f"Failed to write to port: {e}") from e

    def detach(self):
        try:
            self.ser.write(b"AT+CGNSPWR=0\r\n")
            response = self.ser.readline().decode('utf-8').strip()
            if response != "OK":
                raise IOError(f"Failed to power off GNSS: {response}")
            return True
        except serial.SerialException as e:
            raise IOError(f"Failed to write to port: {e}") from e

    def get_data(self):
        try:
            while self.ser.in_waiting > 0:
                line = self.ser.readline().decode('utf-8').strip()
                if line.startswith('$GPRMC') and len(line.split(',')) > 2:
                    status = line.split(',')[2]
                    if status == 'A':
                        return line.split(',')
            return None
        except serial.SerialException as e:
            raise IOError(f"Failed to read from port: {e}") from e

    def close(self):
        if self.ser.is_open:
            self.ser.close()

def signal_handler(sig, frame):
    print("Received signal, closing port...")
    if 'gps_controller' in globals():
        gps_controller.close()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    with GPSController() as gps_controller:
        if not gps_controller.attach():
            print("Failed to attach GPS")
            sys.exit(1)

        while True:
            data = gps_controller.get_data()
            if data:
                print("Received GPRMC data:", data)
            time.sleep(1)

