class SimpleGPS:
    def __init__(self, port='/dev/serial0', baudrate=9600):
        self.port = port
        self.baudrate = baudrate
        self.ser = None

    def connect(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=1)
            logger.info(f"Connected to {self.port} at {self.baudrate} baud")
            return True
        except OSError as e:
            logger.error(f"Failed to connect to {self.port}: {e}")
            return False

    def read_data(self):
        if self.ser is None:
            logger.error("Serial port is not open")
            return None
        try:
            data = self.ser.readline().decode('utf-8', errors='ignore').strip()
            return data if data else None
        except serial.SerialException as e:
            logger.error(f"Serial read error: {e}")
            self.close()
            return None

    def parse_gga(self, line):
        if not line.startswith('$GPGGA') and not line.startswith('$GNGGA'):
            return None
        try:
            fields = line.split(',')
            utc_time = fields[1]
            latitude = self.parse_coordinate(fields[2], fields[3])
            longitude = self.parse_coordinate(fields[4], fields[5])
            fix_quality = int(fields[6])
            num_satellites = int(fields[7])
            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except (IndexError, ValueError) as e:
            logger.error(f"Malformed GGA sentence: {e}")
            return None

    def parse_coordinate(self, value, hemisphere):
        if not value:
            return None
        degrees, minutes = value.split('.')
        degrees = int(degrees)
        minutes = float(minutes) / 60
        coordinate = degrees + minutes
        if hemisphere == 'S' or hemisphere == 'W':
            coordinate = -coordinate
        return coordinate

    def close(self):
        if self.ser:
            try:
                self.ser.close()
                logger.info(f"Closed {self.port}")
            except serial.SerialException as e:
                logger.error(f"Failed to close {self.port}: {e}")
            self.ser = None

def main():
    gps = SimpleGPS()
    if not gps.connect():
        return

    try:
        while True:
            data = gps.read_data()
            if data:
                parsed = gps.parse_gga(data)
                if parsed:
                    logger.info(f"Parsed GGA: {parsed}")
    except KeyboardInterrupt:
        logger.info("Shutting down...")
