import os
import signal
import threading
import time
from contextlib import contextmanager
from flask import Flask, jsonify, request, abort
from gpiozero import Device
from picamera2 import Picamera2
from adafruit_circuitpython_bus_device import I2CDevice
from paho.mqtt import client as mqtt_client
import serial

app = Flask(__name__)
uart_lock = threading.Lock()
uart_port = None
data_list = [{'id': 1, 'name': 'Item 1', 'done': False}, {'id': 2, 'name': 'Item 2', 'done': False}]
data_lock = threading.Lock()

@contextmanager
def safe_uart_open(port, baudrate, timeout):
    global uart_port
    with uart_lock:
        if uart_port is None:
            try:
                uart_port = serial.Serial(port, baudrate, timeout=timeout)
            except serial.SerialException as e:
                yield None, e
            else:
                yield uart_port, None
        else:
            yield uart_port, None

@app.route('/version', methods=['GET'])
def get_version():
    with safe_uart_open('/dev/ttyUSB0', 9600, 1) as (port, error):
        if error:
            return "Error opening UART port", 500
        if port is None:
            return "UART port already open", 500
        try:
            port.write(b'*IDN?\n')
            port.flush()
            response = port.readline().decode('ascii').strip()
            return response, 200
        except serial.SerialTimeoutException:
            return "Timeout reading from UART port", 504
        except Exception as e:
            return "Error reading from UART port", 502

@app.route('/data', methods=['GET'])
def get_data():
    with data_lock:
        return jsonify(data_list), 200

@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_item(item_id):
    with data_lock:
        item = next((item for item in data_list if item['id'] == item_id), None)
        if item:
            return jsonify(item), 200
        else:
            return "Item not found", 404

@app.route('/data', methods=['POST'])
def post_data():
    data = request.get_json()
    if 'name' not in data or not data['name']:
        return "Invalid name", 400
    if 'done' not in data or not isinstance(data['done'], bool):
        return "Invalid done value", 400
    with data_lock:
        new_item = {'id': max(item['id'] for item in data_list) + 1, 'name': data['name'], 'done': data['done']}
        data_list.append(new_item)
        return jsonify(new_item), 201

def signal_handler(sig, frame):
    global uart_port
    if uart_port:
        uart_port.close()
    app.logger.info('Shutting down gracefully')
    os._exit(0)

if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    app.run(host='0.0.0.0', port=5000, debug=False)

