import serial
import time
import sys

def read_oximeter_data():
    try:
        ser = serial.Serial('/dev/ttyUSB0', 9600, bytesize=serial.EIGHTBITS, parity=serial.PARITY_NONE, stopbits=serial.STOPBITS_ONE, timeout=1)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            line = ser.readline().decode('ascii', errors='replace').strip()
            if not line:
                continue

            fields = line.split(',')
            if len(fields) != 2:
                print(f"Warning: Invalid data format - {line}", file=sys.stderr)
                continue

            heart_rate, spo2 = fields
            print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting gracefully...", file=sys.stderr)
    finally:
        ser.close()

if __name__ == "__main__":
    read_oximeter_data()

