import json
import time
import serial
from flask import Flask, request, jsonify, abort
from gpiozero import LED
from picamera2 import Picamera2
from adafruit_circuitpython_ina219 import INA219
from paho.mqtt import client as mqtt_client
import atexit

app = Flask(__name__)

# Initialize serial connection
try:
    ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
except serial.SerialException as e:
    app.logger.error(f"Failed to open serial port: {e}")
    exit(1)

# Initialize in-memory list
data = ["Item 1", "Item 2"]

# Initialize GPIO LED
led = LED(17)

# Initialize camera
camera = Picamera2()
camera.start()

# Initialize INA219
ina219 = INA219(0x40, 1)

# Initialize MQTT client
mqtt_broker = "mqtt.eclipse.org"
mqtt_client = mqtt_client.Client()
mqtt_client.connect(mqtt_broker)
mqtt_client.loop_start()

# Cleanup function to release resources
def cleanup():
    ser.close()
    camera.stop()
    mqtt_client.loop_stop()
    mqtt_client.disconnect()

atexit.register(cleanup)

@app.route('/version', methods=['GET'])
def get_version():
    try:
        ser.write(b"*IDN?\n")
        time.sleep(0.1)
        response = ser.read_all().decode('utf-8').replace('\n', '<br>')
        return response, 200, {'Content-Type': 'text/html'}
    except serial.SerialException as e:
        app.logger.error(f"Serial read error: {e}")
        return "Service Unavailable", 503

@app.route('/getdata', methods=['GET'])
def get_data():
    return jsonify(data)

@app.route('/getset/<int:item_id>', methods=['GET'])
def get_set(item_id):
    if item_id < 0 or item_id >= len(data):
        abort(404)
    return jsonify(data[item_id])

@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def get_post(item_id, name):
    data.append({"id": item_id, "name": name, "done": False})
    return jsonify(data)

@app.route('/postjson', methods=['POST'])
def post_json():
    if request.is_json:
        content = request.get_json()
    elif request.form:
        content = request.form.to_dict()
    else:
        abort(400)

    try:
        new_id = max(item['id'] for item in data) + 1 if data else 1
        name = content.get('name', '')
        done = content.get('done', 'false').lower() in ['true', '1', 't', 'y', 'yes']
        data.append({"id": new_id, "name": name, "done": done})
        return jsonify(data), 201
    except Exception as e:
        app.logger.error(f"Error processing JSON data: {e}")
        abort(400)

@app.route('/postjson', methods=['GET'])
def get_post_json():
    return jsonify(data)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

