import serial
import time

def send_command_over_rfcomm(command, port='/dev/rfcomm4', baudrate=38400):
    try:
        with serial.Serial(port, baudrate, timeout=1) as ser:
            ser.write(f'X{command}\n'.encode())
            ser.flush()
            time.sleep(0.1)
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to connect to the Bluetooth device: {e}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to send command over RFCOMM: {e}") from e

def main():
    try:
        while True:
            command = input("Enter command: ")
            if command.lower() == "exit":
                break
            send_command_over_rfcomm(command)
    except KeyboardInterrupt:
        print("\nExiting gracefully...")
    finally:
        print("Program terminated.")

if __name__ == "__main__":
    main()

